const doc = { version: 3, orderId: 'A-42', lines, shippedAt: iso };

const wire = JSON.stringify(doc);                    // producer

let got;
try {
  got = JSON.parse(wire);
} catch (e) {                                        // SyntaxError => invalid message
  deadLetter(wire, e.message);
  return;
}
if (!isOrderShipped(got)) return ignore(got);         // receiver decides
handle(got);
